fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Split the string into lines based on line endings
            let mut lines: Vec<String> = Vec::new();
            let mut current_line = String::new();
            let mut chars = s.chars().peekable();

            while let Some(c) = chars.next() {
                if c == '\n' {
                    // If we encounter a newline, we finalize the current line
                    if keepends {
                        current_line.push(c);
                    }
                    if !current_line.is_empty() {
                        lines.push(current_line.clone());
                        current_line.clear();
                    }
                } else {
                    current_line.push(c);
                }
            }

            // Add the last line if it's not empty
            if !current_line.is_empty() {
                lines.push(current_line);
            }

            lines
        })
        .collect()
}